package org.springframework.samples.petclinic.rest.function.owner;

import java.time.DayOfWeek;
import java.time.LocalDate;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.RequestBody;

@Validated
public class BuildOwner {

    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
            Out<Boolean> sharesHousehold) {
        Owner owner = ownerMapper.toOwner(request);
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            registrationDate = LocalDate.now();
        }
        // The effective registration date must fall on a business day: roll a Saturday
        // or Sunday forward to the following Monday. Applies whether the date was
        // supplied in the request or defaulted to the server date. Every value derived
        // from the registration date (membership number, daily create-limit) reads it
        // back from the owner, so adjusting here keeps them consistent.
        owner.setRegistrationDate(rollForwardToBusinessDay(registrationDate));
        built.set(owner);
        // sharesHousehold is a create-time flag, not an Owner field; republish it for
        // RejectDuplicateHousehold. Absent in the body means false.
        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
    }

    private static LocalDate rollForwardToBusinessDay(LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        if (day == DayOfWeek.SATURDAY) {
            return date.plusDays(2);
        }
        if (day == DayOfWeek.SUNDAY) {
            return date.plusDays(1);
        }
        return date;
    }
}

